// The real board UI and orchestration with fake accounts. Simulated transport is opt-in.
import {spawnSync} from 'node:child_process';
import {readFileSync,writeFileSync,cpSync} from 'node:fs';
import {resolve,join} from 'node:path';
const dest=resolve(process.argv[2]||'');if(!process.argv[2])throw Error('Informe diretório novo.');
const result=spawnSync(process.execPath,[new URL('./live-board-demo.mjs',import.meta.url).pathname,dest],{encoding:'utf8'});if(result.status)throw Error(result.stderr);
const web=join(dest,'public'),path=join(web,'quadro/index.html');let html=readFileSync(path,'utf8');
html=html.replace('let saved;',`if(params.get('failure')==='register')CRISBridge.registerLiveHost=async()=>{throw Object.assign(Error('permission denied'),{code:'42501'});};
        if(params.get('transport')==='simulated'){const {SimPeer}=await import('../live-peer-simulated.js');window.Peer=SimPeer;const pause=document.createElement('button');pause.id='qaPause';pause.textContent='Pausar rede simulada';pause.onclick=()=>{window.LIVE_QA.drop();SimPeer.online=false;};const resume=document.createElement('button');resume.id='qaResume';resume.textContent='Retomar rede simulada';resume.onclick=()=>{SimPeer.online=true;};document.querySelector('#qaTools').append(pause,resume);}
        Object.assign(CRISBridge,{saveBoard:async()=>{},loadSheet:async()=>null});
        const {mountBoardSession}=await import('./board-session.js?v=337');
        await mountBoardSession(identity,{bridge:CRISBridge,client:async()=>{const q=new Proxy({}, {get:(t,k)=>k==='then'?resolve=>resolve({data:[],error:null}):()=>q});return {from:()=>q};}});
        let saved;`);
html=html.replace("document.body.append(capture);","capture.hidden=true;document.body.append(capture);");
html=html.replace('<aside style=', '<aside id="qaTools" style=');
html=html.replace('</body>',`<style>body:has(#vwJoin) #qaTools{visibility:hidden}body.visual-qa #qaTools{display:none}</style><script>if(new URLSearchParams(location.search).has('visual'))document.body.classList.add('visual-qa');</script></body>`);
writeFileSync(path,html);cpSync(new URL('./live-peer-simulated.js',import.meta.url),join(web,'live-peer-simulated.js'));
let qa=readFileSync(join(web,'live-board-qa.js'),'utf8');qa=qa.replace("$('#shLink')?.value||new URLSearchParams(location.search).get('sala')","$('#shCodeB')?.textContent||window.CRIS_BOARD_ENTRY?.current?.room||new URLSearchParams(location.search).get('sala')");qa=qa.replace('transport:d?.transport,',"cinematic:window.CRIS_REMOTE_CINEMATICS?.diagnostics?.(),roomView:window.CRIS_ROOM_CONTROLS?.view,transport:d?.transport,");
qa+=`\nimport {defaultCamera,newEffect,lightingProfile} from './campaign-director/dist/cinematic-direction-model.js';
const complex=document.createElement('button');complex.id='qaComplex';complex.textContent='Cinematic WebM de teste';document.querySelector('#qaTools').append(complex);
complex.onclick=async()=>{const load=async(name,type)=>new Blob([await(await fetch('../qa-media/'+name)).arrayBuffer()],{type});const bg=await load('palco.png','image/png'),fallback=await load('iris.png','image/png'),video=await load('iris.webm','video/webm');const imageId=await imageKey(bg),fallbackId=await imageKey(fallback),videoId=await imageKey(video);await qaLink.present({userId:window.CRIS_IDENTITY.userId,boardCampaignId:window.CRISBridge.campaignId},{campaignId:'qa',pageId:'theater',sceneId:'test'},{id:'qa-complex',name:'Teatro em camadas',imageId,motion:'living',seconds:12,intensity:12,ending:'loop',fadeIn:.2,fadeOut:.3,camera:defaultCamera(),lighting:lightingProfile(),layers:[{id:'iris',name:'Íris',imageId:fallbackId,visible:true,x:.5,y:.6,scale:.35,parallax:1,anchor:{x:.5,y:1},effects:[newEffect('breath')],video:{mediaId:videoId,enabled:true,loop:true,rate:1,delay:0,end:'fallback',transparent:true}}]},{[imageId]:bg,[fallbackId]:fallback,[videoId]:video});};\n`;
writeFileSync(join(web,'live-board-qa.js'),qa);
writeFileSync(join(web,'room-qa.html'),`<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LIVE-01B.1 · interface real em teste</title><style>body{margin:0;background:#14110f;color:#ddd0b8;font:13px system-ui}nav{display:flex;gap:10px;align-items:center;padding:8px;flex-wrap:wrap}button,select{padding:8px}main{display:flex;gap:12px;align-items:flex-start;transform-origin:top left}iframe{border:0;flex:none;height:820px}body.wide main{zoom:.7}pre{white-space:pre-wrap}#note{margin:8px}</style><nav><strong>QA · contas fictícias</strong><label>Largura <select id="width"><option>390</option><option>360</option><option>768</option><option>1024</option><option>1440</option></select></label><label>Vista <select id="view"><option value="both">Duas telas</option><option value="master">Mestre</option><option value="player">Jogador</option></select></label><button data-action="qaCinematic">Simples</button><button data-action="qaComplex">WebM</button><button data-action="qaCinematicStop">Encerrar Cinematic</button><button data-action="qaImage">Imagem no quadro</button><button data-action="qaDrop">Simular queda</button><button data-action="qaPause">Pausar rede simulada</button><button data-action="qaResume">Retomar rede simulada</button><button id="newPlayer">Reabrir jogador</button><button id="report">Ler diagnóstico</button></nav><p id="note">Transporte SIMULADO por BroadcastChannel de QA. Interface, PeerSession, LiveWire, prova, orquestração e CinematicFrame reais. Não homologa WebRTC nem RLS.</p><main><iframe id="masterBoard" title="Mestre" style="width:900px"></iframe><iframe id="playerBoard" title="Jogador" style="width:390px"></iframe></main><pre id="result"></pre><script>
const params=new URLSearchParams(location.search),testCase=params.get('case')||'recovery-'+Date.now(),transport=params.get('real')?'':'&transport=simulated';
document.querySelector('#note').textContent=params.has('real')?'PeerJS/WebRTC REAIS · contas fictícias. Este navegador compartilha perfil; não homologa Windows/Android nem RLS.':'Transporte SIMULADO · interface, PeerSession, LiveWire, prova e CinematicFrame reais. Não homologa WebRTC nem RLS.';
const base='quadro/?case='+testCase+'&visual=1'+transport,master=document.querySelector('#masterBoard'),player=document.querySelector('#playerBoard');master.src=base;player.src=base+'&user=room-'+testCase;
document.querySelector('#view').onchange=e=>{master.hidden=e.target.value==='player';player.hidden=e.target.value==='master';};
document.querySelector('#width').onchange=e=>{const w=+e.target.value;player.style.width=w+'px';master.style.width=w+'px';document.body.classList.toggle('wide',w>768);};
for(const b of document.querySelectorAll('[data-action]'))b.onclick=()=>master.contentDocument.getElementById(b.dataset.action)?.click();
document.querySelector('#newPlayer').onclick=()=>player.src=base+'&user=room-'+testCase;
document.querySelector('#report').onclick=()=>document.querySelector('#result').textContent=JSON.stringify({master:JSON.parse(master.contentDocument.getElementById('qaReport').textContent||'{}'),player:JSON.parse(player.contentDocument.getElementById('qaReport').textContent||'{}')},null,2);
</script></html>`);
console.log(dest);
